L10_1.m_Talk_SCN = "\232\191\153\232\175\157\230\136\145\231\187\143\229\184\184\229\144\172\229\147\166\239\188\140\229\147\165\229\147\165\239\188\159\232\191\153\231\174\151\230\152\175\232\135\170\230\136\145\229\143\141\231\156\129\229\144\151\239\188\159"
